const source = $input.first()?.json ?? {};
const now = new Date();
const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Seoul',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  weekday: 'short'
}).formatToParts(now);

const year = parts.find((p) => p.type === 'year')?.value;
const month = parts.find((p) => p.type === 'month')?.value;
const day = parts.find((p) => p.type === 'day')?.value;
const weekdayName = parts.find((p) => p.type === 'weekday')?.value;

if (!year || !month || !day || !weekdayName) {
  throw new Error('Failed to resolve current date in Asia/Seoul.');
}

const todayInt = Number(`${year}${month}${day}`);
const todayDate = `${year}-${month}-${day}`;
const todayMMDD = `${month}${day}`;
const isWeekend = ['Sat', 'Sun'].includes(weekdayName);

return [{
  json: {
    ...source,
    Year: Number(year),
    Month: Number(month),
    Day: Number(day),
    WeekdayName: weekdayName,
    IsWeekend: isWeekend,
    DefaultIsHoliday: isWeekend,
    DefaultHolidayName: isWeekend ? '\uC8FC\uB9D0' : '\uD3C9\uC77C',
    todayInt,
    todayDate,
    todayMMDD
  }
}];

const baseline = $('Weekday Baseline').first()?.json ?? {};
const today = String(baseline.todayDate || '');

if (!today) {
  return [];
}

const matches = $input.all()
  .filter((item) => {
    const data = item?.json ?? {};
    const startDate = String(data.property_date?.start || '');
    const endDate = String(data.property_date?.end || startDate || '');
    return Boolean(startDate) && today >= startDate && today <= endDate;
  })
  .map((item, index) => ({
    json: item.json,
    pairedItem: item.pairedItem ?? { item: index },
  }));

if (matches.length > 0) {
  return matches;
}

return [{
  json: {
    today_vacation_filter_applied: true,
    today_vacation_match_count: 0,
    today_date: today,
  },
  pairedItem: { item: 0 },
}];
